/* Isolated UI state only. No persistence, scoring, model calls or profile writes. */
window.AssessmentPreview=(()=>{
 'use strict';
 const {esc,icon,button:B,link:L,top,bottle}=UI;
 let C;const state={factor:null,count:3,screen:{},answer:{},scores:{}};
 const names={'single-factor':'单因子测评','daily-checkin':'每日打卡','short-16pf':'简化版16PF','personality-sandbox':'模拟性格','ai-reset':'AI 重置版'};
 const tag=t=>`<span class="preview-status">${t}</span>`;
 const head=(route,desc)=>`${top('认识')}<header class="preview-heading">${tag('界面预览 · 正式功能待实现')}<h1>${names[route]}</h1><p>${desc}</p></header>`;
 const unavailable=(label,why)=>`<div class="preview-unavailable">${B(label,'preview-unavailable',{cls:'btn full',disabled:true})}<p>${why}</p></div>`;
 const controls=(route,label='查看作答布局')=>B(label,'preview-stage',{cls:'btn secondary full','data-id':route,'data-stage':'process',after:'arrow'});
 function home(s){
  const sess=s.sessions.find(x=>x.id===s.activeSession),unfinished=sess?.status==='in-progress',done=sess?.status==='completed',a=s.actions.find(x=>x.status==='active');
  const action=unfinished?'resume':done?'nav':'start',params=done?{'data-route':'review','data-id':sess.id}:{};
  return `<header class="v3-home-heading"><h1>你好，今天的你</h1><p>留一点时间，认识自己</p></header><section class="home-scene" aria-label="16PF 性格探索"><div class="home-portrait"><div class="v4-person-scene" aria-hidden="true"><span></span><i></i><i></i><img src="assets/person-${s.avatar}.svg" alt=""></div></div><h2>16PF 性格探索</h2><p class="home-scene-sub">每一种你，都值得了解。</p><div class="home-primary-grid" aria-label="两种主要探索方式">
   ${B(`${tag('交互示例')}<strong>16PF 原版</strong><small>3题示例，不计分<br>正式题源待接入</small><span class="entry-action">${unfinished?'继续上次作答':done?'回看这次作答':'查看作答体验'} ${icon('arrow','sm')}</span>`,action,{cls:'home-primary',...params})}
   ${L(`${tag('待开放')}<strong>AI 重置版</strong><small>内容、计分<br>与效度待验证</small><span class="entry-action">查看设计预览 ${icon('arrow','sm')}</span>`,'ai-reset',{cls:'home-primary'})}
  </div></section><section class="home-paths" aria-label="四种轻探索"><p>选一种方式，慢慢认识</p><div class="home-secondary-grid">
  ${[['single-factor','bottle','单因子测评','从16因子选一个'],['daily-checkin','sun','每日打卡','每天3–5题的设计'],['short-16pf','book','简化版16PF','少量情境题<br>非标准测试'],['personality-sandbox','explore','模拟性格','手动设置<br>假设探索']].map(([r,i,t,d])=>L(`${icon(i)}<strong>${t}</strong><small>${d}</small>`,r,{cls:'home-path'})).join('')}</div><p class="home-preview-note">以上为设计预览，不提供正式测评或AI分析。</p></section>
  ${unfinished?`<p class="home-resume-note">原版示例已保存 ${Object.keys(sess.answers).length} / 3 题，继续同一份作答。</p>`:done?B('再体验一次原版示例','start-new',{cls:'textbtn full'}):''}
  ${a?L(`${icon('flag')}<span class="grow"><strong>回看自己的小尝试</strong><small>${esc(a.text)}</small></span>${icon('arrow','sm')}`,'action-detail',{cls:'v3-action-resume','data-id':a.id}):''}<p class="v3-endnote">知遇测评 · 从性格到生活里的自己</p>`;
 }
 function stage(route){
  const result=state.screen[route]==='result',selected=state.answer[route];
  return `<section class="preview-paper"><div class="preview-section-head"><h2>${result?'结果区域预览':'作答过程预览'}</h2>${tag('布局示例')}</div>${result?`<div class="preview-empty">${icon('book')}<h3>这里将呈现你的探索</h3><p>题源、映射和解读规则尚未接入。当前没有分数、因子结论或画像更新。</p></div>${B('返回作答布局','preview-stage',{cls:'btn secondary full','data-id':route,'data-stage':'process'})}`:`<p class="small muted">示例 1 / ${route==='daily-checkin'?state.count:'—'} · 不关联正式因子</p><h3 class="space-16">遇到一个新的安排，你更愿意先做什么？</h3><p class="small muted">这段原创文案只展示布局，不属于正式测评题库。</p><div class="preview-options" role="group" aria-label="布局示例选项">${[['a','先弄清楚具体要求'],['b','先想想自己的感受'],['c','看看情况，再决定']].map(([id,t])=>B(t,'preview-answer',{cls:'option '+(selected===id?'selected':''),'data-id':route,'data-value':id,'aria-pressed':String(selected===id)})).join('')}</div><p class="small muted" role="status">${selected?'已选择 · 仅当前页面预览，不保存为本人作答':'选择后可查看结果空状态，不计算结果。'}</p>${B('查看结果区域','preview-stage',{cls:'btn secondary full space-16','data-id':route,'data-stage':'result',disabled:!selected})}`}</section>${B('返回配置','preview-stage',{cls:'textbtn full','data-id':route,'data-stage':'config'})}`;
 }
 function single(){const route='single-factor',f=D.factors.find(f=>f[0]===state.factor);return head(route,'一次只看一个角度，选择你想进一步了解的因子。')+(state.screen[route]&&state.screen[route]!=='config'?stage(route):`<section class="preview-paper"><div class="preview-section-head"><h2>选择一个因子</h2><span>${f?'已选 1 / 16':'尚未选择'}</span></div><div class="factor-picker">${D.factors.map(f=>B(`${bottle([f[0],f[1],null,f[3]])}<strong>${esc(f[1])}</strong><small>${f[0]}</small>`,'preview-factor',{cls:'factor-choice '+(f[0]===state.factor?'selected':''),'data-id':f[0],'aria-pressed':String(f[0]===state.factor),'aria-label':f[0]+' '+f[1]})).join('')}</div><div class="preview-selection" role="status"><h3>${f?esc(f[0]+' · '+f[1]):'先选一个想了解的角度'}</h3><p>${f?esc(f[4])+'。高低不等于好坏；当前没有本人分数。':'选中后查看对应任务的页面布局。题源与单因子计分规则待实现。'}</p></div>${B('查看所选因子的作答布局','preview-stage',{cls:'btn secondary full','data-id':route,'data-stage':'process',disabled:!f})}${f?B('清除选择','preview-clear-factor',{cls:'textbtn full'}):''}</section>${unavailable('开始正式单因子测评','正式题源、映射与计分尚未接入。预览选择不会新建答卷。')}`);}
 function daily(){const route='daily-checkin';return head(route,'每天留一点时间，用几个问题多认识自己一点。')+(state.screen[route]&&state.screen[route]!=='config'?stage(route):`<section class="preview-paper"><div class="preview-section-head"><h2>今天的小探索</h2>${tag('暂无可用题组')}</div><div class="preview-empty">${icon('sun')}<h3>等待题库就绪</h3><p>未来从维护的题库中，结合个人画像与过去问题，选择你未做过且适配的问题。当前尚未接入题库、画像或筛选服务。</p></div><fieldset class="preview-fieldset"><legend>题组数量预览</legend><div class="preview-count">${[3,4,5].map(n=>B(n+' 题','preview-count',{cls:n===state.count?'selected':'','data-value':n,'aria-pressed':String(n===state.count)})).join('')}</div></fieldset><p class="small muted">默认范围为每天3–5题；题库不足等策略待确认。本页不读取个人画像。</p>${controls(route)}</section>${unavailable('开始今日打卡','题库与适配规则尚未就绪。布局预览不会产生打卡记录或画像更新。')}`);}
 function short(){const route='short-16pf';return head(route,'用少量较复杂的情境题，探索一个或多个性格角度。')+(state.screen[route]&&state.screen[route]!=='config'?stage(route):`<section class="preview-paper"><div class="preview-section-head"><h2>把想法放进情境里</h2>${tag('非标准测试')}</div><div class="preview-example"><span class="eyebrow">题型方向 · 待设计</span><h3>同一个情境，可以有不同考虑</h3><p>未来题目可能覆盖一个或多个16PF因子；界面会容纳较长情境、选择与补充表达。</p></div><dl class="preview-facts"><div><dt>题目数量</dt><dd>待确定</dd></div><div><dt>因子映射与计分</dt><dd>待设计、验证</dd></div><div><dt>效度与准确率</dt><dd>尚无验证结论</dd></div></dl><p class="preview-boundary">简化版的题目、计分与验证尚未完成，目前不生成分数，不能与原版直接比较。</p>${controls(route)}</section>${unavailable('开始简化版探索','题库、映射、计分与验证尚未完成。当前仅展示页面风格与流程布局。')}`);}
 function sandbox(){const route='personality-sandbox',count=Object.keys(state.scores).length;return head(route,'调整16个因子的位置，预览这组设定；当前不生成性格分析。')+(state.screen[route]==='result'?`<section class="preview-paper"><h2>假设配置预览</h2><p>以下仅是你手动设置的值，不是系统分析，不代表任何真人。</p><div class="preview-score-summary">${D.factors.map(f=>`<div><span>${esc(f[0]+' '+f[1])}</span><strong>${state.scores[f[0]]??'未设置'}</strong></div>`).join('')}</div><div class="preview-empty"><h3>假设解读尚未开放</h3><p>未来可基于这组假设配置分析；当前不生成AI性格结论，也不写入个人画像。</p></div>${B('继续调整假设','preview-stage',{cls:'btn secondary full','data-id':route,'data-stage':'config'})}</section>`:`<section class="preview-paper"><div class="preview-section-head"><h2>16个因子，自己设定</h2><span id="sandbox-count">已设置 ${count} / 16</span></div><p id="sandbox-scale" class="preview-boundary">0–10仅是界面示意尺度，不是16PF常模或正式分数；滑杆初始中点不代表已填写。</p><div class="preview-sliders">${D.factors.map(f=>`<div class="preview-slider"><label for="hypothesis-${f[0]}">${esc(f[0]+' · '+f[1])}</label><output for="hypothesis-${f[0]}" id="value-${f[0]}">${state.scores[f[0]]??'未设置'}</output><input id="hypothesis-${f[0]}" type="range" min="0" max="10" step="1" value="${state.scores[f[0]]??5}" data-preview-score="${f[0]}" aria-describedby="sandbox-scale"><div class="slider-extents"><span>0 · 示意低位</span><span>10 · 示意高位</span></div></div>`).join('')}</div>${B('查看假设配置','preview-stage',{cls:'btn secondary full','data-id':route,'data-stage':'result'})}${B('清空全部假设值','preview-clear-scores',{cls:'textbtn full'})}<p class="small muted">设置仅留在当前页面会话；刷新清空，不存入本人记录。</p></section>${unavailable('分析假设性格','分析服务尚未接入。可先查看配置布局，不生成虚构AI结果。')}`);}
 function ai(){return head('ai-reset','与原版并列的一条探索路径，内容与体验仍在设计中。')+`<section class="preview-paper"><h2>一种新的提问方式</h2><p>这里预留AI重置版的探索入口。题源、计分、效度与实际模型能力都尚未接入或验证。</p><div class="preview-empty">${icon('sparkle')}<h3>正式内容准备中</h3><p>当前仅展示设计说明，暂不生成 AI 分析；与原版的可比性尚未验证。</p></div>${unavailable('开始AI重置版','当前不可开始正式测评。你可以返回认识，查看其他页面设计。')}${L('返回认识','home',{cls:'btn secondary full'})}</section>`;}
 function repaintChoice(action,value){C.repaint();document.querySelector('[data-action="'+CSS.escape(action)+'"][data-value="'+CSS.escape(value)+'"]')?.focus({preventScroll:true});}
 function dispatch(action,el){const d=el?.dataset||{};switch(action){
  case 'preview-factor':if(D.factors.some(f=>f[0]===d.id)){state.factor=d.id;C.repaint();}return true;
  case 'preview-clear-factor':state.factor=null;C.repaint();return true;
  case 'preview-count':if([3,4,5].includes(Number(d.value))){state.count=Number(d.value);repaintChoice(action,d.value);}return true;
  case 'preview-answer':if(names[d.id]&&['a','b','c'].includes(d.value)){state.answer[d.id]=d.value;repaintChoice(action,d.value);}return true;
  case 'preview-stage':if(names[d.id]&&['config','process','result'].includes(d.stage)){state.screen[d.id]=d.stage;C.repaint();document.querySelector('.preview-paper h2')?.setAttribute('tabindex','-1');document.querySelector('.preview-paper h2')?.focus();}return true;
  case 'preview-clear-scores':state.scores={};C.repaint();C.toast('已清空当前预览的假设值。');return true;
  default:return false;
 }}
 document.addEventListener('input',e=>{const code=e.target.dataset.previewScore;if(!D.factors.some(f=>f[0]===code))return;state.scores[code]=Math.min(10,Math.max(0,Number(e.target.value)));document.getElementById('value-'+code).textContent=state.scores[code];document.getElementById('sandbox-count').textContent='已设置 '+Object.keys(state.scores).length+' / 16';});
 Object.assign(Views.map,{'single-factor':single,'daily-checkin':daily,'short-16pf':short,'personality-sandbox':sandbox,'ai-reset':ai});
 return {home,getStage(){return state.screen[C?.current().split('?')[0]]||'config';},isQuiet(){return C&&state.screen[C.current().split('?')[0]]==='process';},bind(c){C=c;},dispatch,afterRender(){const r=C.current().split('?')[0];if(names[r])document.title=names[r]+' · 知遇测评';}};
})();
